INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "本纪记思州战事平息", "description": "永乐十二年正月庚寅，《明史》本纪记载，明廷在思州与当地苗民的战事平息。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年正月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "88c1a26e-bf5b-5dbc-b79b-e10956706066"}, {"title": "明廷征调十五万人运粮到宣府", "description": "永乐十二年正月辛丑，朝廷征调山东、山西、河南、凤阳、淮安、徐州和邳州共十五万民众，将粮食运到宣府。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年正月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ba9ba7a8-9739-5d3a-b89c-765701f9ed4c"}, {"title": "明成祖检阅军队", "description": "永乐十二年二月己酉，明成祖朱棣举行大规模阅兵。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年二月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d3954861-852a-5e36-82ad-80a3b7e81da2"}, {"title": "明成祖亲征瓦剌并安排各部将领", "description": "永乐十二年二月庚戌，明成祖朱棣决定亲征瓦剌。柳升领大营，郑亨领中军，陈懋与李彬分别领左、右哨，王通与谭青分别领左、右掖，刘江和朱荣任前锋。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6ea004c-e0c9-5d74-bff2-e52b768abe14"}, {"title": "明廷救济凤翔、陇州饥民并查办瞒报官员", "description": "永乐十二年二月庚申，明廷救济凤翔、陇州的饥民，查办未上报灾情的地方主管官员。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年二月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "124e9bb3-3bb5-532c-9c27-388e63dfcaf5"}, {"title": "张辅在老挝俘获陈季扩", "description": "永乐十二年三月癸未，张辅在老挝俘获陈季扩，将他献给明廷。《明史》本纪将这一行动作为此次交阯战事平息的标志。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年三月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c01e2a41-fe72-5190-9ba2-47852f09b1c2"}, {"title": "明成祖从北京出征，朱瞻基随行", "description": "永乐十二年三月庚寅，明成祖朱棣从北京启程出征，皇太孙朱瞻基随行。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年三月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "25dfbd2f-60b5-58ef-a9d3-0663b95a101b"}, {"title": "明成祖到兴和检阅军队", "description": "永乐十二年四月初一，明成祖朱棣行至兴和，并在那里举行大规模阅兵。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年四月甲辰朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "851e4fb1-1568-571d-b651-d96894d065c6"}, {"title": "明廷颁布军中的奖惩号令", "description": "永乐十二年四月己酉，明廷向随征部队颁布赏罚号令。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年四月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7d413f8a-857b-5997-a658-771f13bf50d0"}, {"title": "明廷设置军中传令与记功官", "description": "永乐十二年四月庚戌，明廷设置负责传令、记录战功的军中官员。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年四月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2062d08-7789-572b-bf27-2f8c4c8abfd2"}, {"title": "明军驻屯云谷时接受孛罗不花等人归降", "description": "永乐十二年四月丁卯，明军行至屯云谷，孛罗不花等人前来归降。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年四月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1e097c0c-b672-5fe7-8424-9d1396603159"}, {"title": "明成祖派官员督阵并记录将士表现", "description": "永乐十二年五月丁丑，明成祖命尚书、光禄卿、给事中等官员督阵，查察将士是否遵令尽力作战。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年五月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5efdbbed-09b9-5955-9044-b1437b32874a"}, {"title": "刘江在康哈里孩击败瓦剌军", "description": "永乐十二年六月甲辰，刘江在康哈里孩遇到瓦剌部队，交战后将其击败。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年六月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a79d9212-54d1-5449-b92c-cc84098535c3"}, {"title": "明军在忽兰忽失温击败马哈木所部", "description": "永乐十二年六月戊申，明成祖率军到达忽兰忽失温。瓦剌首领马哈木率部来战，明军将其击败，追至土剌河。马哈木趁夜退走。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年六月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b92fd37b-bb4a-55e8-a0aa-85ab39ba166d"}, {"title": "明军班师并向阿鲁台通报战果", "description": "永乐十二年六月庚戌，明军班师，并将战胜瓦剌的消息告知阿鲁台。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年六月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5484f66-ffd9-5cf8-b3ed-8422c492e824"}, {"title": "明军行至三峰山，阿鲁台派使者来朝", "description": "永乐十二年六月戊午，明军行至三峰山。阿鲁台派遣使者前来朝见。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年六月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3169be1d-d3ab-50c0-bc2e-964f59060cc8"}, {"title": "明廷下诏公布击败瓦剌的消息", "description": "永乐十二年六月己巳，朝廷颁诏公布击败瓦剌的战果。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年六月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e9c49a4e-b9d5-5a72-b6c3-e933463d3257"}, {"title": "明廷禁止军队入关践踏庄稼、夺取民产", "description": "永乐十二年七月戊子，军队行至红桥。明成祖下诏，军队入关后如有践踏庄稼或夺取百姓牲畜财产者，按军法处置。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年七月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b964cac7-ad77-5c57-a7a5-0cef5f0c7169"}, {"title": "皇太子派使者在沙河迎接北征回师", "description": "永乐十二年七月己亥，明成祖率军行至沙河。皇太子朱高炽派使者前来迎接。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年七月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d14cb4bb-9958-50b3-95e8-ffc5388948d4"}, {"title": "明成祖回到北京并在奉天殿受贺", "description": "永乐十二年八月初一，明成祖朱棣到达北京，在奉天殿接受朝贺。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年八月辛丑朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c5e687b1-706c-5ca0-8dc3-55d7a4ca1a90"}, {"title": "明廷免除北京州县两年租税", "description": "永乐十二年八月丙午，明廷免去北京所辖州县两年的租税。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年八月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28bdb8de-6676-5cd9-bcaf-73b2d4640a5e"}, {"title": "明廷赏赐随征将士", "description": "永乐十二年八月戊午，明廷赏赐参加北征的将士。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年八月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ff411223-2571-5b77-a421-55f0efd4623d"}, {"title": "郭亮、徐亨奉命驻防开平", "description": "永乐十二年九月癸未，朝廷派郭亮、徐亨在开平布防。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "643d11f3-2b05-5d60-8330-ec29160767ea"}, {"title": "本纪记靖州战事平息", "description": "永乐十二年九月丙戌，《明史》本纪记载，明廷在靖州与当地苗民的战事平息。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年九月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e500bdcd-c35e-55db-9af6-fa1adc32645c"}, {"title": "费瓛镇守甘肃，刘江镇守辽东", "description": "永乐十二年九月甲午，朝廷派费瓛镇守甘肃，派刘江镇守辽东。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年九月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf960fa3-d947-59b8-9591-44b40d203f16"}, {"title": "黄淮被关入监狱", "description": "永樂12年（1414年）闰九月，黄淮被关入监狱。", "start_year": 1414, "end_year": 1414, "time_original": "永樂12年（1414年）闰九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "e4a03a90-bf45-552a-ae5b-c62e10708c23"}, {"title": "金问、杨溥、芮善因迎驾迟缓被下狱", "description": "永乐十二年闰九月甲辰，明成祖以皇太子派使者迎驾迟缓为由，下令拘捕东宫属官。金问、杨溥和芮善在此次处分中被下狱。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年闰九月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "092599fa-0f8d-5913-9c4f-0ee843f097d8"}, {"title": "杨士奇被关入监狱，不久获特赦并恢复职务", "description": "永樂12年（1414年）闰九月，杨士奇被关入监狱，不久获特赦并恢复职务。", "start_year": 1414, "end_year": 1414, "time_original": "永樂12年（1414年）闰九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "d30d042a-c05a-5b2b-a154-b5768c7e8105"}, {"title": "吴高奉召返回", "description": "永乐十二年闰九月甲子，朝廷召吴高返回。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年闰九月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0c424834-db6a-509b-af57-7bd100bdd0f1"}, {"title": "都督朱荣奉命镇守大同", "description": "永乐十二年闰九月丁卯，朝廷派都督朱荣镇守大同。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年闰九月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "288a1aa5-9654-565a-973d-323abc8abcc2"}, {"title": "朝廷复审在押囚犯", "description": "永乐十二年十一月甲辰，朝廷审录在押囚犯。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年十一月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d0fe95b3-9576-5549-971a-5f0363522bb9"}, {"title": "晋王朱济熺被废为庶人", "description": "永乐十二年十一月庚戌，明廷废去晋王朱济熺的爵位，将他降为庶人。", "start_year": 1414, "end_year": 1414, "time_original": "永乐十二年十一月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "09498687-6c59-5827-b6cb-3f234d9c325f"}, {"title": "明廷豁免苏州等地水灾田租", "description": "永乐十二年十一月庚申，朝廷减免苏州、松江、杭州、嘉兴、湖州因水灾所涉田租，共四十七万九千余石。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十二年十一月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6d21ec3b-bf84-5fb1-b69e-6ca64baadf5b"}, {"title": "沙的新葛来朝并受封为王", "description": "永乐十二年，泥八剌的沙的新葛来到明廷，受封为王。本纪将此列于年末汇记。 按原历纪年，事情发生在公元1414至1415年之间。", "start_year": null, "end_year": null, "time_original": "永乐十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8dc33df9-795e-52fe-a2ef-73d4292a8c93"}, {"title": "本纪汇记永乐十二年多地入贡", "description": "永乐十二年，彭亨和乌斯藏入贡，真腊进献金缕衣，琉球中山王贡马，榜葛剌进献本纪称作麒麟的动物。 按原历纪年，事情发生在公元1414至1415年之间。", "start_year": null, "end_year": null, "time_original": "永乐十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1748e52e-2f99-56a7-bdac-2130f1016e61"}, {"title": "明廷堵塞居庸关以北的险要通道", "description": "永乐十三年正月丙午，明廷下令封堵居庸关以北的隘口。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年正月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e14d4d4f-70bf-586b-bd09-359ba6207997"}, {"title": "明廷接受马哈木请罪与朝贡请求", "description": "永乐十三年正月丁未，瓦剌首领马哈木向明廷请罪，并请求朝贡，明廷予以准许。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年正月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9d39d326-f000-53a1-ab08-84291168a441"}, {"title": "北京午门失火", "description": "永乐十三年正月壬子，北京午门发生火灾。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年正月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "610384a8-ba71-5ab2-83ef-f149c75dfd14"}, {"title": "明廷命豁免积欠并宽赦获罪军人", "description": "永乐十三年正月戊午，朝廷命内外各官署豁免积欠，并宽赦获罪的将士和军官。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年正月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3115298b-5cd0-5bdd-b2f3-867215ace97b"}, {"title": "明廷派刘斌等人巡查各地军务", "description": "永乐十三年二月癸酉，明廷派指挥刘斌、给事中张磐等十二人巡查山西、山东、大同、陕西、甘肃、辽东，查实军士操练和屯田事务后上报。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年二月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6772c0bb-7025-5b8f-b5eb-27a461b46a65"}, {"title": "明廷命行在礼部主持会试", "description": "永乐十三年二月甲戌，明廷命行在礼部组织会试，选拔各地贡士。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年二月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "08297ec6-8e99-582c-90ed-047b0846251d"}, {"title": "张辅等人从交阯带兵回师", "description": "永乐十三年二月癸未，张辅等人率军从交阯返回。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年二月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "67990c16-f26e-5138-b0ee-86ec623566f9"}, {"title": "明廷按平定交阯的战功分别赏赐", "description": "永乐十三年二月戊子，明廷评定交阯战事中的功劳，按功劳大小给予不同赏赐。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年二月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "39d8633a-2584-5387-abba-2132060975c1"}, {"title": "明廷在北京策试并授陈循等人进士资格", "description": "永乐十三年三月己亥，明廷在北京策试考生，给陈循等人授予不同等第的进士资格。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年三月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "df6a67bf-3e71-530a-9000-5e1875aff2fb"}, {"title": "葛森出兵平定广西一带反抗", "description": "永乐十三年三月丙午，本纪记广西一些当地居民反抗明廷，指挥同知葛森出兵平息。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年三月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0a4e2513-3ca0-5ad6-bac1-bd582a65d31a"}, {"title": "张辅奉命镇守交阯", "description": "永乐十三年四月戊辰，明廷派张辅镇守交阯。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年四月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "09041594-6ec7-54b6-a27d-88e3441bcf69"}, {"title": "五月初一发生日食", "description": "永乐十三年五月初一，发生日食。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年五月丁酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b790e8bb-ed00-57f1-af39-75555eea4442"}, {"title": "明廷开凿清江浦，打通通往北京的漕运", "description": "永乐十三年五月乙丑，明廷开凿清江浦，以疏通向北京运粮的水路。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年五月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e6a5fad9-ef3a-50a6-adec-f481a4af86e7"}, {"title": "明廷救济北京、河南和山东的水灾", "description": "永乐十三年六月，明廷对北京、河南和山东的水灾地区施行救济。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "209acf18-2b0d-5d12-9c82-9f15a251047a"}, {"title": "郑和归来", "description": "永乐十三年七月癸卯，《明史》本纪记郑和归来。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年七月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "40052500-a1de-584f-8863-4925a6f7601a"}, {"title": "本纪记四川戎县山都掌战事平息", "description": "永乐十三年七月乙巳，《明史》本纪记四川戎县山都掌一带与明廷的战事平息。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年七月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c556356-6063-5906-afd8-73ddabdda96d"}, {"title": "明廷赈济山东、河南和顺天府饥民", "description": "永乐十三年八月庚辰，朝廷赈济山东、河南及北京顺天府所属州县的饥民。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年八月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6b7f18c6-4bee-5da9-acca-db9c243ad29d"}, {"title": "北京发生地震", "description": "永乐十三年九月壬戌，北京发生地震。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年九月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a3a54808-c92d-5719-970f-3cb7a4098960"}, {"title": "明成祖前往近郊打猎", "description": "永乐十三年十月甲申，明成祖朱棣到近郊打猎。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年十月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02ffd079-113f-586f-a70d-fbbc2a986f36"}, {"title": "明成祖听取侵吞官粮案报告后，下令处死涉案者", "description": "永乐十三年十月壬辰，主管司法的官署奏报侵吞冒领官粮一案。明成祖朱棣发怒，下令处死涉案者，后在复奏时改令依法裁决。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年十月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "904c0bfe-8f73-50bb-9c84-e1d6b3262d31"}, {"title": "明成祖改令依法办案，重申死刑案件须五次复奏", "description": "永乐十三年十月，在司法机关复奏侵冒官粮案时，明成祖朱棣承认原先的处置有过失，改令依照律法裁决，并要求此后所有死刑案件均须五次复奏，定为法令。", "start_year": 1415, "end_year": 1415, "time_original": "永乐十三年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0efbe1de-05a5-53e7-854c-eb33d9739744"}, {"title": "明廷减免顺天等地水旱灾区的田租", "description": "永乐十三年十二月，朝廷减免顺天、苏州、凤阳、浙江、湖广、河南和山东受水灾或旱灾影响州县的田租。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2fcf625-990e-5ebc-9226-e3e71c90ba7a"}, {"title": "本纪汇记永乐十三年多地入贡", "description": "永乐十三年，琉球山南、山北和爪哇西王等来贡，麻林等地进献被本纪记为麒麟、天马、神鹿的动物，琉球中山有两次入贡记录。 按原历纪年，事情发生在公元1415至1416年之间。", "start_year": null, "end_year": null, "time_original": "永乐十三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ff451f3b-2699-5d7f-bf15-44163f017bd7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

